// ============================================================
// Build JSON Structure — C1 HSCH Exam Builder
// ============================================================
// يُحوّل البيانات الخام المُخصَّبة إلى هيكل JSON النهائي
// مع تقسيم النصوص إلى segments عند كل _____
// ============================================================

const raw = $input.item.json;

const text_de = String(raw.text_de || '').trim();
const text_ar = String(raw.text_ar || '').trim();
const optionsRaw = raw.options_enriched || raw.options || [];
const answersRaw = raw.answers || [];
const section = Number(raw.section || 0);
const section_name = String(raw.section_name || '').trim();
const model = Number(raw.model || 0);
const model_name = String(raw.model_name || '').trim();
const slug = String(raw.slug || '').trim().toLowerCase().replace(/\s+/g, '-');
const chatId = String(raw.chatId || '');
const firstName = String(raw.firstName || 'صديقي');

// -------------------------------------------------------
// دالة بناء الـ segments
// -------------------------------------------------------
function buildSegments(text) {
  const BLANK = '_____';
  const parts = text.split(BLANK);
  const segments = [];
  let blankId = 0;
  parts.forEach((part, idx) => {
    if (part !== '') segments.push({ type: 'text', content: part });
    if (idx < parts.length - 1) segments.push({ type: 'blank', id: blankId++ });
  });
  return { segments, totalBlanks: blankId };
}

const deResult = buildSegments(text_de);
const arResult = buildSegments(text_ar);
const totalBlanks = deResult.totalBlanks;

// -------------------------------------------------------
// تطبيع الخيارات
// -------------------------------------------------------
const options = Array.isArray(optionsRaw) ? optionsRaw.map(o => ({
  key: String(o.key || '').toLowerCase(),
  de: String(o.de || ''),
  ar: String(o.ar || ''),
  keywords: {
    de: String((o.keywords && o.keywords.de) || ''),
    ar: String((o.keywords && o.keywords.ar) || '')
  }
})) : [];

// -------------------------------------------------------
// تطبيع مفاتيح الإجابات
// -------------------------------------------------------
let correctKeys = [];
if (Array.isArray(answersRaw)) {
  if (answersRaw.length > 0 && typeof answersRaw[0] === 'string') {
    correctKeys = answersRaw.map(k => String(k).toLowerCase());
  } else if (answersRaw.length > 0 && typeof answersRaw[0] === 'object') {
    correctKeys = answersRaw
      .sort((a, b) => (Number(a.id) || 0) - (Number(b.id) || 0))
      .map(a => String(a.correct_key || '').toLowerCase());
  }
}

// -------------------------------------------------------
// بناء مصفوفة الإجابات (options الكاملة في id:0 فقط)
// -------------------------------------------------------
const answers = [];
for (let i = 0; i < totalBlanks; i++) {
  if (i === 0) {
    answers.push({ id: 0, correct_key: correctKeys[0] || '', options });
  } else {
    answers.push({ id: i, correct_key: correctKeys[i] || '' });
  }
}

// -------------------------------------------------------
// بناء JSON النهائي
// -------------------------------------------------------
const finalJson = {
  meta: {
    app: 'c1_hsch',
    section,
    section_name,
    model,
    model_name,
    level: 'C1',
    total_blanks: totalBlanks
  },
  text: {
    de: [{ type: 'paragraph', segments: deResult.segments }],
    ar: [{ type: 'paragraph', segments: arResult.segments }]
  },
  answers
};

// -------------------------------------------------------
// مسار الملف الديناميكي
// -------------------------------------------------------
const filename = `s${section}_m${model}_${slug}.json`;
const filePath = `assets/data/section_${section}/${filename}`;
const fileContent = JSON.stringify(finalJson, null, 2);

return [{ json: {
  finalJson,
  fileContent,
  filePath,
  filename,
  section,
  section_name,
  model,
  model_name,
  slug,
  totalBlanks,
  optionsCount: options.length,
  chatId,
  firstName
} }];

// فحص نتيجة رفع GitHub
// يستقبل من Create أو Update (حصرياً واحدة منهما)

const result = $input.item.json;
const buildData = $('Build JSON Structure').item.json;

// GitHub success: returns { content: {...}, commit: {...} }
// GitHub error (continueOnFail): { error: {...}, message: '...' }
const isSuccess = result.content !== undefined && !result.error;

if (!isSuccess) {
  const errorMsg = (
    (result.errors && result.errors[0] && result.errors[0].message) ||
    result.message ||
    (result.error && typeof result.error === 'string' ? result.error : JSON.stringify(result.error)) ||
    'GitHub API Error'
  );
  return [{ json: {
    success: false,
    errorMessage: errorMsg,
    timestamp: new Date().toISOString(),
    ...buildData
  } }];
}

const commitUrl = (result.commit && result.commit.html_url) ||
  `https://github.com/alshalabi011-dotcom/c1_hsch/blob/main/${buildData.filePath}`;

return [{ json: {
  success: true,
  commitUrl,
  timestamp: new Date().toISOString(),
  ...buildData
} }];

// تهيئة رسالة النجاح للمشرف
const d = $input.item.json;

const lines = [
  '✅ *تم رفع ملف جديد على GitHub*',
  '',
  `📄 *الملف:* \`${d.filename}\``,
  `📂 *المسار:* \`${d.filePath}\``,
  `📝 *النموذج:* ${d.model_name}`,
  `🏷 *القسم:* ${d.section} — ${d.section_name}`,
  `🔢 *الفراغات:* ${d.totalBlanks}`,
  `🔤 *الخيارات:* ${d.optionsCount}`,
  `👤 *أضافه:* ${d.firstName} (chatId: ${d.chatId})`,
  `⏰ *الوقت:* ${d.timestamp}`,
  `🔗 ${d.commitUrl}`
];

return [{ json: { ...d, adminMsg: lines.join('\n') } }];

// تهيئة رسالة الخطأ للمشرف
// يُرسل تفاصيل الخطأ + أول 2500 حرف من JSON للمشرف

const d = $input.item.json;
const maxLen = 2500;
const jsonPreview = (d.fileContent || '{}').substring(0, maxLen);
const isTruncated = (d.fileContent || '').length > maxLen;

const lines = [
  '🚨 *فشل رفع ملف على GitHub!*',
  '',
  `📄 *الملف:* \`${d.filename || 'unknown'}\``,
  `📂 *المسار:* \`${d.filePath || 'unknown'}\``,
  `❌ *الخطأ:* ${d.errorMessage || 'خطأ غير معروف'}`,
  `⏰ *الوقت:* ${d.timestamp || new Date().toISOString()}`,
  `👤 *المستخدم:* ${d.firstName || 'مجهول'} (chatId: ${d.chatId || 'N/A'})`,
  '',
  '📋 *محتوى الملف (للاحتفاظ بنسخة):*',
  '```json',
  jsonPreview,
  isTruncated ? '...\n(النص مقطوع لأنه أطول من 2500 حرف)' : '',
  '```'
];

return [{ json: { ...d, adminErrorMsg: lines.join('\n') } }];

// العقدة الأخيرة الموحدة — نقطة العودة لـ Sub-WF 1
// تستقبل من مسار النجاح أو مسار الخطأ (حصرياً)

const d = $input.item.json;

if (d.success) {
  return [{ json: {
    success: true,
    filename: d.filename,
    filePath: d.filePath,
    model_name: d.model_name,
    totalBlanks: d.totalBlanks,
    optionsCount: d.optionsCount,
    section: d.section,
    section_name: d.section_name,
    commitUrl: d.commitUrl,
    timestamp: d.timestamp,
    chatId: d.chatId
  } }];
}

return [{ json: {
  success: false,
  errorMessage: 'حدث خطأ أثناء الرفع على GitHub. تم إبلاغ المشرف وحُفظت نسخة من الملف.',
  filename: d.filename,
  filePath: d.filePath
} }];
